CREATE TABLE IF NOT EXISTS gis_phase39116_lineage_decisions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), run_id uuid NOT NULL REFERENCES gis_phase39116_lineage_runs(id), candidate_match_id uuid NOT NULL, prior_status text NOT NULL, lineage_sources jsonb NOT NULL DEFAULT '[]'::jsonb, geometry_evidence jsonb NOT NULL DEFAULT '{}'::jsonb, inec_evidence jsonb NOT NULL DEFAULT '{}'::jsonb, decision text NOT NULL, errors jsonb NOT NULL DEFAULT '[]'::jsonb, fingerprint text NOT NULL UNIQUE, candidate_mutation boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());